from pathlib import Path
import hashlib

source_path = Path('tools/ats_question_triage.py')
regression_path = Path('tests/test_ats_question_triage_autonomous.py')
immutable_path = Path('tests/test_ats_question_triage.py')
expected_blob = '8b4d37223ee08c0add0d5b349875a8e8983cd0d9'


def git_blob_sha1(data):
    header = b'blob ' + str(len(data)).encode('ascii') + b'\0'
    return hashlib.sha1(header + data).hexdigest()


immutable_before = immutable_path.read_bytes()
if git_blob_sha1(immutable_before) != expected_blob:
    raise RuntimeError('Immutable test Git blob identity mismatch')

if not source_path.is_file() or not regression_path.is_file():
    raise RuntimeError('Previously completed ATS files are missing')

original_source = source_path.read_text(encoding='utf-8')
original_tests = regression_path.read_text(encoding='utf-8')

required_source = [
    'mismatched_contact_control',
    'field.get("ambiguous", False) is not False',
    'invalid_field_metadata',
]
required_tests = [
    'def test_mismatched_contact_controls_require_review(',
    'def test_nonboolean_ambiguity_metadata_requires_review(',
    'def test_malformed_contact_metadata_requires_review(',
]

if any(item not in original_source for item in required_source):
    raise RuntimeError('Previously completed classifier safeguards are missing')

if any(item not in original_tests for item in required_tests):
    raise RuntimeError('Previously completed autonomous regressions are missing')

if 'invalid_verified_keys' in original_source:
    raise RuntimeError('Verification-container safeguard already exists')

if 'def test_invalid_verified_key_containers_require_review(' in original_tests:
    raise RuntimeError('Requested verification-container regressions already exist')

anchor = "    for metadata_key in ('question', 'label'):\n"
if original_source.count(anchor) != 1:
    raise RuntimeError('Expected metadata-validation anchor not found exactly once')

insert = '''    if not isinstance(verified_keys, (set, frozenset)) or any(
        not isinstance(key, str) for key in verified_keys
    ):
        return {'status': 'human_review', 'reason': 'invalid_verified_keys'}
'''

additional_tests = '''

@pytest.mark.parametrize('verified_keys', [
    'email',
    'full_name',
    ['email'],
    ('email',),
    {'email': True},
    {'email': False},
    {'email': 'verified'},
    {},
    [],
    (),
    b'email',
    None,
    0,
    1,
    True,
])
def test_invalid_verified_key_containers_require_review(verified_keys):
    result = classify_field(
        {
            'question': 'Email',
            'label': 'Email',
            'type': 'email',
            'ambiguous': False,
        },
        verified_keys,
    )
    assert result == {
        'status': 'human_review',
        'reason': 'invalid_verified_keys',
    }


@pytest.mark.parametrize('verified_keys', [
    {'email', None},
    {'email', 1},
    {'email', False},
    frozenset({'email', None}),
    frozenset({'email', 1}),
    {None},
    {1},
    frozenset({1}),
    {'email', b'phone'},
])
def test_nonstring_verified_key_members_require_review(verified_keys):
    result = classify_field(
        {
            'question': 'Email',
            'label': 'Email',
            'type': 'email',
            'ambiguous': False,
        },
        verified_keys,
    )
    assert result == {
        'status': 'human_review',
        'reason': 'invalid_verified_keys',
    }


@pytest.mark.parametrize('verified_keys', [
    {'email'},
    frozenset({'email'}),
    {'email', 'unused'},
    frozenset({'email', 'unused'}),
])
def test_valid_verified_key_containers_preserve_candidates(verified_keys):
    result = classify_field(
        {
            'question': 'Email',
            'label': 'Email',
            'type': 'email',
            'ambiguous': False,
        },
        verified_keys,
    )
    assert result == {
        'status': 'verified_candidate',
        'profile_key': 'email',
    }


@pytest.mark.parametrize('verified_keys', [set(), frozenset()])
def test_empty_verified_key_containers_preserve_unverified_review(verified_keys):
    result = classify_field(
        {
            'question': 'Email',
            'label': 'Email',
            'type': 'email',
            'ambiguous': False,
        },
        verified_keys,
    )
    assert result == {
        'status': 'human_review',
        'reason': 'unverified_profile_fact',
    }


def test_invalid_verified_keys_never_expose_candidate_or_answer():
    result = classify_field(
        {
            'question': 'Full name',
            'label': 'Full name',
            'type': 'text',
            'ambiguous': False,
        },
        {'full_name': False},
    )
    assert result == {
        'status': 'human_review',
        'reason': 'invalid_verified_keys',
    }
    assert 'profile_key' not in result
    assert 'answer' not in result
    assert 'value' not in result


@pytest.mark.parametrize('verified_keys', [
    {'email'},
    frozenset({'email'}),
])
def test_verified_key_validation_preserves_existing_safeguards(verified_keys):
    fields = [
        {'question': 'Email', 'label': 'Email', 'type': 'email', 'ambiguous': False},
        {'question': 'Email', 'label': 'Email', 'type': 'tel', 'ambiguous': False},
        {'question': 'Email', 'label': 'Email', 'type': 'email', 'ambiguous': None},
        {'question': None, 'label': 'Email', 'type': 'email', 'ambiguous': False},
        {'question': 'Referee email', 'label': 'Referee email', 'type': 'email', 'ambiguous': False},
        {'question': 'Email', 'label': 'Email', 'type': 'select-one', 'ambiguous': False},
        {'question': 'Phone', 'label': 'Phone', 'type': 'tel', 'ambiguous': False},
    ]
    assert triage_fields(fields, verified_keys) == [
        {'status': 'verified_candidate', 'profile_key': 'email'},
        {'status': 'human_review', 'reason': 'mismatched_contact_control'},
        {'status': 'human_review', 'reason': 'ambiguous_question'},
        {'status': 'human_review', 'reason': 'invalid_field_metadata'},
        {'status': 'human_review', 'reason': 'unknown_question'},
        {'status': 'human_review', 'reason': 'nontrivial_control'},
        {'status': 'human_review', 'reason': 'unverified_profile_fact'},
    ]


def test_invalid_verified_container_preserves_triage_result_order():
    fields = [
        {'question': 'Email', 'label': 'Email', 'type': 'email', 'ambiguous': False},
        {'question': 'Phone', 'label': 'Phone', 'type': 'tel', 'ambiguous': False},
        {'question': 'GitHub', 'label': 'GitHub', 'type': 'url', 'ambiguous': False},
    ]
    assert triage_fields(fields, ['email', 'phone', 'github']) == [
        {'status': 'human_review', 'reason': 'invalid_verified_keys'},
        {'status': 'human_review', 'reason': 'invalid_verified_keys'},
        {'status': 'human_review', 'reason': 'invalid_verified_keys'},
    ]
'''

updated_source = original_source.replace(anchor, insert + anchor, 1)
updated_tests = original_tests.rstrip('\n') + '\n' + additional_tests

compile(updated_source, str(source_path), 'exec')
compile(updated_tests, str(regression_path), 'exec')

if immutable_path.read_bytes() != immutable_before:
    raise RuntimeError('Immutable test changed before implementation')

source_written = False
tests_written = False
try:
    source_path.write_text(updated_source, encoding='utf-8')
    source_written = True
    regression_path.write_text(updated_tests, encoding='utf-8')
    tests_written = True
    if immutable_path.read_bytes() != immutable_before:
        raise RuntimeError('Immutable test changed during implementation')
    if git_blob_sha1(immutable_path.read_bytes()) != expected_blob:
        raise RuntimeError('Immutable test Git blob identity changed')
except BaseException:
    if source_written:
        source_path.write_text(original_source, encoding='utf-8')
    if tests_written:
        regression_path.write_text(original_tests, encoding='utf-8')
    raise
